"""Benchmark report rendering."""

from multi_agent_research_lab.core.schemas import BenchmarkMetrics


def render_markdown_report(metrics: list[BenchmarkMetrics]) -> str:
    """Render benchmark metrics to markdown, with a comparison table and analysis section."""

    lines = [
        "# Benchmark Report",
        "",
        "Auto-generated by `multi_agent_research_lab.evaluation.report`. Each row averages "
        "results across the configured benchmark queries (see `configs/lab_default.yaml`).",
        "",
        "| Run | Latency (s) | Cost (USD) | Quality | Citation cov. | Failure rate | Notes |",
        "|---|---:|---:|---:|---:|---:|---|",
    ]
    for item in metrics:
        cost = "" if item.estimated_cost_usd is None else f"{item.estimated_cost_usd:.4f}"
        quality = "" if item.quality_score is None else f"{item.quality_score:.1f}"
        citation = "" if item.citation_coverage is None else f"{item.citation_coverage:.0%}"
        failure = "" if item.failure_rate is None else f"{item.failure_rate:.0%}"
        lines.append(
            f"| {item.run_name} | {item.latency_seconds:.2f} | {cost} | {quality} "
            f"| {citation} | {failure} | {item.notes} |"
        )

    lines.append("")
    lines.append(_render_comparison(metrics))
    return "\n".join(lines) + "\n"


def _render_comparison(metrics: list[BenchmarkMetrics]) -> str:
    by_name = {m.run_name: m for m in metrics}
    baseline = by_name.get("baseline")
    multi = by_name.get("multi-agent")
    if not baseline or not multi:
        return ""

    lines = ["## Baseline vs Multi-Agent"]
    latency_delta = multi.latency_seconds - baseline.latency_seconds
    latency_pct = (
        (latency_delta / baseline.latency_seconds * 100) if baseline.latency_seconds else 0
    )
    lines.append(
        f"- **Latency**: multi-agent is {latency_delta:+.2f}s ({latency_pct:+.0f}%) vs baseline."
    )

    if baseline.estimated_cost_usd is not None and multi.estimated_cost_usd is not None:
        cost_delta = multi.estimated_cost_usd - baseline.estimated_cost_usd
        cost_pct = (
            (cost_delta / baseline.estimated_cost_usd * 100) if baseline.estimated_cost_usd else 0
        )
        lines.append(
            f"- **Cost**: multi-agent is ${cost_delta:+.4f} ({cost_pct:+.0f}%) vs baseline "
            "(more LLM calls: researcher + analyst + writer vs one baseline call)."
        )

    if baseline.quality_score is not None and multi.quality_score is not None:
        quality_delta = multi.quality_score - baseline.quality_score
        lines.append(f"- **Quality**: multi-agent is {quality_delta:+.1f} points vs baseline.")

    if baseline.citation_coverage is not None and multi.citation_coverage is not None:
        cov_delta = multi.citation_coverage - baseline.citation_coverage
        lines.append(f"- **Citation coverage**: multi-agent is {cov_delta:+.0%} vs baseline.")

    lines.append(
        f"- **Failure rate**: baseline {baseline.failure_rate:.0%}, "
        f"multi-agent {multi.failure_rate:.0%}."
    )

    lines.append("")
    lines.append("## Failure modes observed")
    lines.append(
        "- **Supervisor loop guardrail**: if Researcher/Analyst keep failing (e.g. LLM "
        "timeout), the Supervisor still forces `done` once `max_iterations` is hit, so the "
        "workflow always terminates with a best-effort (possibly partial) answer instead of "
        "hanging."
    )
    lines.append(
        "- **Search returns nothing**: `SearchClient` (offline corpus or Tavily) may return "
        "zero sources for an off-topic query. The Researcher then records "
        '`"No sources were found"` instead of crashing, and downstream agents degrade '
        "gracefully (Analyst/Writer note the missing evidence)."
    )
    lines.append(
        "- **LLM call failure after retries**: `LLMClient.complete` retries transient errors "
        "(timeout/rate limit) 3x with exponential backoff, then raises `AgentExecutionError`. "
        "Each worker agent catches this and falls back to a best-effort output (e.g. Writer "
        "stitches together analysis/research notes) rather than aborting the whole run — this "
        "is why `failure_rate` can be non-zero while a `final_answer` still exists."
    )
    lines.append(
        "- **Fix applied**: added per-agent try/except around LLM calls with fallback content, "
        "plus `CriticAgent` as a cheap deterministic validator that flags citation gaps or "
        "too-short answers without spending another LLM call."
    )
    return "\n".join(lines)
